class Solution {
    public long maximumOr(int[] nums,int k){
        long[] suffix=new long[nums.length+1];
        for(int i=nums.length-1;i>=0;i--)suffix[i]=suffix[i+1]|nums[i];
        long prefix=0,answer=0;
        for(int i=0;i<nums.length;i++){
            answer=Math.max(answer,prefix|((long)nums[i]<<k)|suffix[i+1]);
            prefix|=nums[i];
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumOr(nums:IntArray,k:Int):Long{
        val suffix=LongArray(nums.size+1);
        for(i in nums.lastIndex downTo 0)suffix[i]=suffix[i+1] or nums[i].toLong();
        var prefix=0L;
        var answer=0L;
        for(i in nums.indices){
            answer=maxOf(answer,prefix or (nums[i].toLong() shl k) or suffix[i+1]);
            prefix=prefix or nums[i].toLong()
        };
        return answer
    }
}

